        Consider a function $f : \R^n \rightarrow \R$ and denote the set of points at which $f$ is not differentiable by $\Omega$. For $x \notin \Omega$, $p \in \R^n$ with $\nabla f(x)^\top p < 0$, and $c_1, c_2 \in (0,1)$, $c_1 < c_2$, a step length $t > 0$ satisfies the \emph{Wolfe conditions}, if $x + t p \notin \Omega$ and


\begin{align}
            f(x + t p) &\leq f(x) + c_1 t \nabla f(x)^\top p, \label{eq:Wolfe_1} \tag{W1} \\
            \nabla f(x + t p)^\top p &\geq c_2 \nabla f(x)^\top p. \label{eq:Wolfe_2} \tag{W2}
        \end{align}

\begin{algorithm} 
            \caption{Quasi-Newton method}
            \label{algo:QN}
            \begin{algorithmic}[1] 
                \Require Initial point $x^0 \in \R^n \setminus \Omega$, initial \spd matrix $H_0 \in \R^{n \times n}$, Wolfe parameters $c_1, c_2 \in (0,1)$, $c_1 < c_2$.
                \For{$k = 0, 1, \dots$}
                    \State If $\nabla f(x^{k}) = 0$ then stop.
                    \State Set $p^k = - H_k \nabla f(x^k)$.
                    \State Set $x^{k+1} = x^k + t_k p^k$, where $t_k$ satisfies the Wolfe conditions \eqref{eq:Wolfe_1} and \eqref{eq:Wolfe_2}.
                    \State If $f$ is not differentiable at $x^{k+1}$ then stop. \label{state:breakdown}
                    \State For $y^k = \nabla f(x^{k+1}) - \nabla f(x^k)$ and $s^k = x^{k+1} - x^k$, compute \label{state:QN_update}
                    \Statex \hspace{\algorithmicindent}a \spd matrix $H_{k+1}$ with $H_{k+1} y^k = s^k$.
                \EndFor
            \end{algorithmic}
        \end{algorithm}

        As in \cite{LO2013}, if the algorithm stops in Step \ref{state:breakdown} with $x^{k+1} \in \Omega$, then we say that it \emph{breaks down}. For $k \in \N \cup \{ 0 \}$ we denote the eigenvalues of $H_k$ by $0 < \lambda_1^k \leq \dots \leq \lambda_n^k$. There are many ways for computing the matrix $H_{k+1}$ in Step \ref{state:QN_update} of Alg.\ \ref{algo:QN}. For all numerical experiments in this article, we use the \emph{BFGS update}, where


\begin{align} \label{eq:BFGS_update} 
            H_{k+1} = V_k H_k V_k^\top + \frac{s^k (s^k)^\top}{(s^k)^\top y^k} \text{ for } V_k = \id - \frac{s^k (y^k)^\top}{(s^k)^\top y^k},
        \end{align}

        with $\id \in \R^{n \times n}$ denoting the identity matrix. Throughout the article, the term \emph{BFGS method} refers to the method that results from using \eqref{eq:BFGS_update} for Step \ref{state:QN_update} of Alg.\ \ref{algo:QN}. For computing the Wolfe step length in the numerical experiments, we use Alg.\ 4.6 from \cite{LO2013}. (However, for our theoretical results, the specific way in which the step length is computed does not matter.) Finally, as in \cite{LO2013}, we do not actually check for differentiability in practice, since there is no reliable way to do so in a numerical setting.


        A function $f : \R^n \rightarrow \R$ is called a \emph{continuous selection} of the functions $f_i : \R^n \rightarrow \R$, $i \in I := \{1,\dots,m\}$, $m \in \N$, on $\R^n$, if $f$ is continuous and 
        \begin{align*}
            f(x) \in \{ f_i(x) : i \in I \} \quad \forall x \in \R^n.
        \end{align*}
        The functions $f_i$ are referred to as \emph{selection functions} of $f$. A selection function $f_i$ is called \emph{active} at $x$ if $f(x) = f_i(x)$. The \emph{active set} at $x$ is defined by $I(x) := \{ i \in I : f(x) = f_i(x) \}$ and the \emph{essentially active set} is defined by
        \begin{align*}
            I_e(x) := \{ i \in I : x \in \mathrm{cl}(\mathrm{int}(\{y \in \R^n : f(y) = f_i(y)\})) \}.
        \end{align*}
        In the following, let $f$ be a continuous selection of $\C^1$-functions. By \cite{U2002}, Proposition 2.24, for every $x \notin \Omega$, the set


\begin{align} \label{eq:def_Ag}
            I_g(x) := \{ i \in I_e(x) : \nabla f(x) = \nabla f_i(x) \}
        \end{align}

        is non-empty. 
        By \cite{S2012}, Corollary 4.1.1, $f$ is locally Lipschitz continuous. By \cite{S2012}, Proposition 4.3.1, the Clarke subdifferential \cite{C1990} of $f$ at $x$ is given by $\partial f(x) = \conv(\{ \nabla f_i(x) : i \in I_e(x) \})$. We say that $x$ is a \emph{(Clarke) critical point} of $f$ if $0 \in \partial f(x)$, which is a necessary condition for local optimality (cf.\ \cite{BKM2014}, Theorem 3.17). Finally, if $f$ is a function such that for every $x \in \R^n$, there is an open neighborhood $U \subseteq \R^n$ of $x$ such that the restriction $f|_U$ is a continuous selection of $\C^1$-functions, then $f$ is called \emph{piecewise differentiable}.


\begin{assum} \label{assum:A1}
        The function $f : \R^n \rightarrow \R$ is a continuous selection of $\C^1$-functions $f_i$, $i \in I = \{1,\dots,m\}$, whose gradients are locally Lipschitz continuous.
    \end{assum}

\begin{align} \label{eq:def_calN}
        \calN(\bar{x}) := \spn(\{ \nabla f_i(\bar{x}) - \nabla f_1(\bar{x}) : i \in \{2,\dots,m\} \}).
    \end{align}

    \begin{behav} \label{behav:B1}
        Assume that Alg.\ \ref{algo:QN} is applied to a function $f$ satisfying \ref{assum:A1} and generates a sequence $(x^k)_k$ and corresponding quasi-Newton matrices $(H_k)_k$ such that
        \begin{enumerate}[leftmargin=1.3cm,label=(B1.\arabic*)]
            \item \label{enum:B1_1} $(x^k)_k$ is an infinite sequence, i.e., Alg.\ \ref{algo:QN} did not break down and $\nabla f(x^k) \neq 0$ for all $k \in \N$,
            \item \label{enum:B1_2} $(x^k)_k$ has a limit $\bar{x} \in \R^n$,
            \item \label{enum:B1_3} for all $i \in I$, the set $\{ k \in \N : i \in I_g(x^k) \}$ is infinite,
            \item \label{enum:B1_4} there are $\sigma_L, \sigma_U \in \R^{>0}$ such that 
            \begin{align*}
                \lambda_j^k \in [\sigma_L,\sigma_U] \quad \forall j \in \{\dim(\calN(\bar{x}))+1,\dots,n\}, k \in \N,
            \end{align*}
            \item \label{enum:B1_5} it holds
            \begin{align*}
                \lim_{k \rightarrow \infty} H_k (\nabla f_i(\bar{x}) - \nabla f_1(\bar{x})) = 0 \quad \forall i \in \{2,\dots,m\}.
            \end{align*}
        \end{enumerate}
    \end{behav}


\begin{assum} \label{assum:A2}
        The function $f : \R^n \rightarrow \R$ satisfies \ref{assum:A1} and
        \begin{enumerate}[leftmargin=1.3cm,label=(A2.\arabic*)]
            \item \label{enum:A2_1} $f$ has a critical point $x^*$ with
                \begin{itemize}
                    \item $\exists \alpha \in \R^m$ with $\alpha_i > 0$ for all $i \in I$ and $\sum_{i = 1}^m \alpha_i \nabla f_i(x^*) = 0$,
                    \item the vectors $\nabla f_i(x^*)$, $i \in I$, are affinely independent,
                \end{itemize}
            \item \label{enum:A2_2} $x^*$ is the unique global minimum and there is some $z \in \R^n \setminus \{ x^* \}$ such that $\calL(z) := \{ x \in \R^n : f(x) \leq f(z) \}$ is bounded.
        \end{enumerate}
    \end{assum}

