proof.raw_tex:
\begin{lemma} \label{lem:common_descent}
        Assume that $f$ satisfies \ref{assum:A1} and that \ref{behav:B1} holds. Then
        \begin{align*}
            \lim_{k \rightarrow \infty} \nabla f_i(x^k)^\top p^k - \nabla f_1(x^k)^\top p^k = 0
            \quad \forall i \in \{2,\dots,m\}.
        \end{align*}
    \end{lemma}

\begin{proof}
        For $k \in \N$ let $i_k \in I_g(x^k)$. Let $i \in \{2,\dots,m\}$. By definition of $p^k$ we have
        \begin{align*}
            \nabla f_i(x^k)^\top p^k - \nabla f_1(x^k)^\top p^k
            = -(\nabla f_i(x^k) - \nabla f_1(x^k))^\top H_k \nabla f_{i_k}(x^k).
        \end{align*}
        Since $x^k \rightarrow \bar{x}$ (by \ref{enum:B1_2}), $(H_k)_k$ is bounded (w.r.t.\ the spectral norm, by \ref{enum:B1_4}), and the selection functions are $\C^1$ (by \ref{assum:A1}), \ref{enum:B1_5} implies 
        \begin{align*}
            &(\nabla f_i(x^k) - \nabla f_1(x^k))^\top H_k \\
            &= (\nabla f_i(\bar{x}) - \nabla f_1(\bar{x}))^\top H_k + (\nabla f_i(x^k) - \nabla f_1(x^k) - (\nabla f_i(\bar{x}) - \nabla f_1(\bar{x})))^\top H_k
            \rightarrow 0
        \end{align*}
        as $k \rightarrow \infty$, completing the proof.
    \end{proof}

\begin{lemma} \label{lem:lower_bound_Wolfe}
        Assume that $f$ satisfies \ref{assum:A1} and let $x \notin \Omega$. Let $c_2 \in (0,1)$ and $p \in \R^n$ with $\nabla f(x)^\top p < 0$. Let $t$ be a step length satisfying the second Wolfe condition \eqref{eq:Wolfe_2}. For $i \in I_g(x + t p)$ let $L$ be a Lipschitz constant of $\nabla f_i$ on $\conv(\{x,x + tp\})$. Then
        \begin{align*}
            t \geq 
            \frac{1}{L \| p \|^2}
            \left( 
            -(1 - c_2) \nabla f(x)^\top p
            +
            (\nabla f(x) - \nabla f_{i}(x))^\top p
            \right).
        \end{align*}
    \end{lemma}

\begin{proof}
        By the second Wolfe condition \eqref{eq:Wolfe_2} it holds $\nabla f_{i}(x + tp)^\top p \geq c_2 \nabla f(x)^\top p$. Subtracting $ \nabla f_{i}(x)^\top p$ on both sides yields
        \begin{equation} \label{eq:proof_lem_lower_bound_Wolfe_1}
            \begin{aligned}
                (\nabla f_{i}(x + tp) - \nabla f_{i}(x))^\top p
                &\geq (c_2 \nabla f(x) - \nabla f_{i}(x))^\top p \\
                &= (c_2 \nabla f(x) - \nabla f(x) + \nabla f(x) - \nabla f_{i}(x))^\top p \\
                &= -(1 - c_2) \nabla f(x)^\top p + (\nabla f(x) - \nabla f_{i}(x))^\top p.
            \end{aligned}
        \end{equation}
        Since $\nabla f_{i}$ is locally Lipschitz continuous by \ref{assum:A1}, the left-hand side of \eqref{eq:proof_lem_lower_bound_Wolfe_1} satisfies 
        \begin{align} \label{eq:proof_lem_lower_bound_Wolfe_2}
            (\nabla f_{i}(x + tp) - \nabla f_{i}(x))^\top p
            \leq \| \nabla f_{i}(x + tp) - \nabla f_{i}(x) \| \| p \|
            \leq t L \| p \|^2
        \end{align}
        for a Lipschitz constant of $\nabla f_i$ on $\conv(\{x,x + tp\})$. Combining \eqref{eq:proof_lem_lower_bound_Wolfe_1} and \eqref{eq:proof_lem_lower_bound_Wolfe_2} completes the proof.
    \end{proof}

\begin{lemma} \label{lem:ker_H_subsequence}
        If $f$ satisfies \ref{assum:A1} and \ref{behav:B1} holds, then $(H_k)_k$ has an accumulation point. Furthermore, for all accumulation points $\bar{H}$ of $(H_k)_k$, it holds $\ker(\bar{H}) = \calN(\bar{x})$.
    \end{lemma}

\begin{proof}
        By \ref{enum:B1_4} the spectral norm of $H_k$ is bounded above by $\sigma_U$ for all $k \in \N$. Thus $(H_k)_k$ must have an accumulation point $\bar{H}$. Let $(k_l)_l \subseteq \N$ be a strictly increasing, infinite sequence with $H_{k_l} \rightarrow \bar{H}$ for $l \rightarrow \infty$. Since $\lambda_j^k \geq \sigma_L$ for all $j \in \{\dim(\calN(\bar{x}))+1,\dots,n\}$, $k \in \N$, we have $\dim(\ker(\bar{H})) \leq \dim(\calN(\bar{x}))$ due to continuity of eigenvalues (see, e.g., \cite{A2013}, Theorem 5.2.2). Thus, it suffices to show that $\calN(\bar{x}) \subseteq \ker(\bar{H})$. To this end, let $v \in \calN(\bar{x})$. Then there are $\alpha_i \in \R$, $i \in \{2,\dots,m\}$, such that $v = \sum_{i = 2}^m \alpha_i (\nabla f_i(\bar{x}) - \nabla f_1(\bar{x}))$. By \ref{enum:B1_5}, we obtain
        \begin{align*}
            \bar{H} v
            = \lim_{l \rightarrow \infty} H_{k_l} v
            = \lim_{l \rightarrow \infty} \sum_{i = 2}^m \alpha_i H_{k_l} (\nabla f_i(\bar{x}) - \nabla f_1(\bar{x}))
            = 0,
        \end{align*}
        so $v \in \ker(\bar{H})$, completing the proof. 
    \end{proof}

\begin{lemma} \label{lem:intermediate_result}
        If $f$ satisfies \ref{assum:A1} and \ref{behav:B1} holds, then $I_e(\bar{x}) = I = \{1,\dots,m\}$ and
        \begin{align} \label{eq:intermediate_result}
            \nabla f_i(\bar{x}) \in \calN(\bar{x}) \quad \forall i \in I.
        \end{align}
        In particular, the vectors $\nabla f_i(\bar{x})$, $i \in I$, are linearly dependent.
    \end{lemma}

\begin{proof}
        The equality $I_e(\bar{x}) = \{1,\dots,m\}$ follows from \ref{enum:B1_3} and the fact that $I_g(x^j) \subseteq I_e(x^j)$ for all $j \in \N$ (cf.\ \eqref{eq:def_Ag}). \\
        \textbf{Part 1:} We first show that $\nabla f(x^k)^\top p^k \rightarrow 0$. To this end, assume that this does not hold. Then there is some $C > 0$ and a strictly increasing, infinite sequence $(k_l)_l \subseteq \N$ with $\nabla f(x^{k_l})^\top p^{k_l} < -C$ for all $l \in \N$. Since the number of selection functions is finite, we can assume w.l.o.g.\ that there is some $i \in I$ with $i \in I_g(x^{k_l + 1})$ for all $l \in \N$. Furthermore, by local Lipschitz continuity of $\nabla f_i$, we can assume w.l.o.g.\ that there is a Lipschitz constant $L > 0$ for $\nabla f_i$ on a superset of $\{ x^{k_l} : l \in \N \}$. By Lemma \ref{lem:lower_bound_Wolfe} we have
        \begin{align*}
            t_{k_l} \geq 
            \underbrace{\frac{1}{L \| p^{k_l} \|^2}}_{\text{(I)}}
            \left( 
            \underbrace{-(1 - c_2) \nabla f(x^{k_l})^\top p^{k_l}}_{\text{(II)}}
            +
            \underbrace{(\nabla f(x^{k_l}) - \nabla f_{i}(x^{k_l}))^\top p^{k_l}}_{\text{(III)}}
            \right).
        \end{align*}
        The fraction (I) is bounded below since $(p^{k_l})_l$ is bounded above due to \ref{enum:B1_2} and \ref{enum:B1_4}. The term (II) is bounded below by $(1 - c_2)C$. The term (III) vanishes by Lemma \ref{lem:common_descent}, since
        \begin{align*}
            \nabla f(x^{k_l}) - \nabla f_{i}(x^{k_l})
            = \nabla f(x^{k_l}) - \nabla f_1(x^{k_l}) - (\nabla f_i(x^{k_l}) - \nabla f_1(x^{k_l})).
        \end{align*}
        Thus, there is some $t_{\text{min}} > 0$ such that $t_{k_l} \geq t_{\text{min}}$ for all $l \in \N$. By the first Wolfe condition \eqref{eq:Wolfe_1}, this implies that
        \begin{align*}
            f(x^{k_l + 1}) - f(x^{k_l}) 
            \leq c_1 t_{k_l} \nabla f(x^{k_l})^\top p^{k_l}
            < - c_1 t_{\text{min}} C
            < 0
            \quad \forall l \in \N,
        \end{align*}
        i.e., the objective value decreases by at least a constant amount infinitely many times. Since $(x^k)_k$ has a limit (by \ref{enum:B1_2}), this contradicts the continuity of $f$. \\
        \textbf{Part 2:} Let $i \in I$. By \ref{enum:B1_3} there is a strictly increasing, infinite sequence $(k_l)_l \subseteq \N$ such that $i \in I_g(x^{k_l})$ for all $l \in \N$. Since $(H_k)_k$ is bounded above by \ref{enum:B1_4}, we can assume w.l.o.g.\ that $(H_{k_l})_l$ converges to some $\bar{H}$. By Part 1, we obtain
        \begin{align*}
            0
            &= \lim_{l \rightarrow \infty} \nabla f(x^{k_l})^\top p^{k_l}
            = -\lim_{l \rightarrow \infty} \nabla f(x^{k_l})^\top H_{k_l} \nabla f(x^{k_l})
            = -\lim_{l \rightarrow \infty} \nabla f_i(x^{k_l})^\top H_{k_l} \nabla f_i(x^{k_l}) \\
            &= -\nabla f_i(\bar{x})^\top \bar{H} \nabla f_i(\bar{x}).
        \end{align*}
        Since $\bar{H}$ is symmetric and positive semidefinite, this implies that $\nabla f_i(\bar{x}) \in \ker(\bar{H})$ (see, e.g., \cite{A2024}, 7.43). Application of Lemma \ref{lem:ker_H_subsequence} completes the proof.
    \end{proof}

\begin{lemma} \label{lem:crit_limit}
        Assume that $f$ satisfies \ref{assum:A1} and \ref{enum:A2_1}. Then there is an open neighborhood $U \subseteq \R^n$ of $x^*$ such if $x \in U$ with $I_e(x) = I = \{1,\dots,m\}$ and $\nabla f_i(x)$, $i \in I$, linearly dependent, then $x$ is a critical point of $f$.
    \end{lemma}

\begin{proof}
