    \end{proof}

\begin{lemma} \label{lem:crit_limit}
        Assume that $f$ satisfies \ref{assum:A1} and \ref{enum:A2_1}. Then there is an open neighborhood $U \subseteq \R^n$ of $x^*$ such if $x \in U$ with $I_e(x) = I = \{1,\dots,m\}$ and $\nabla f_i(x)$, $i \in I$, linearly dependent, then $x$ is a critical point of $f$.
    \end{lemma}

\begin{proof}
